programs.sol:
"""Recognize standalone blanks completing indentation or following a line break.

The strongest negative response is a one-space token after a multi-space
indentation token. It is stronger near the document's beginning. An initial
space has the opposite, large positive response. Ordinary text stays near zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail, line_blank = 0, '', '', True
    else:
        _, position, previous, tail, line_blank = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' ':
        early = (1 + position / 32) ** -0.5
        if position == 0:
            value = 2.434
        elif previous and not previous.strip(' '):
            width = len(previous)
            if width == 1:
                value = -0.03 - 0.33 * line_blank
            elif width == 4:
                value = -0.57 - 0.37 * early
                if not line_blank:
                    value += 0.22
            elif width >= 5:
                value = -0.35 - 0.26 * early
            else:
                value = -0.42 - 0.38 * early
                if width == 2 and not line_blank:
                    value += 0.17
        elif tail.endswith('\\n'):
            value = -0.21
        elif tail.endswith('\n'):
            value = -0.005 - 0.25 * early
        elif previous.endswith((' ', '\t')):
            value = -0.55
        else:
            value = 0.007
    elif token and not token.strip(' '):
        value = 0.03 if len(token) <= 4 else 0.0
        if position == 0:
            value = {2: 1.517, 3: 0.473, 4: 1.341}.get(len(token), 0.5)
    elif token == '\t':
        value = 0.173 if position == 0 else -0.034
    elif token == '\xa0':
        value = -0.096
    if '\n' in token:
        line_blank = not token.rsplit('\n', 1)[1].strip()
    else:
        line_blank = line_blank and not token.strip()
    return (doc, position + 1, token, (tail + token)[-4:], line_blank), value

"""Recognize numbered square-bracket labels and the reopening of quoted speech.

A zero-padded paragraph number gets a positive closing-bracket response;
ending a chain of short citations gets a negative one. Identifier-prefixed
chains are treated as array indexing instead. Ordinary brackets
are mildly positive; number-only initial fragments get an amplified response.
Reopening a quotation after an attribution is negative.
The quotation response weakens with the length of the attribution.
Formatting rules cover escaped newlines, middle dots, degree signs, and
fullwidth punctuation following an ASCII question mark (corrupted text).
Only a bounded text tail is retained, and documents reset it.
"""
import math
import re

READS = ()
REPORTING_VERBS = re.compile(
    r"\b(said|says|told|tells|added|adds|explained|explains|continued|"
    r"replied|asked|reported|reports|stated|wrote)\b", re.I
)


def response(token, before):
    if token == ']':
        number = re.search(r'\[([0-9]+)$', before)
        chain = re.search(r'(?:\[[0-9]{1,3}\])+\[[0-9]{1,3}$', before)
        if chain:
            previous = before[chain.start() - 1:chain.start()]
            return -0.03 if previous.isalnum() or previous == '_' else -1.05
        if number:
            digits = number[1]
            line_start = re.search(r'(?:^|\n)[ \t]*$', before[:number.start()])
            if len(digits) == 4 and digits.startswith('0'):
                return 0.74 if line_start else 0.51
            if len(digits) == 1:
                return 0.07 if digits == '0' else 0.15
            return 0.12 if line_start else 0.03
        if before.isascii() and before.isdigit() and 3 <= len(before) <= 4:
            return 2.8
        return 0.08
    if token in (' “', ' "'):
        # A previous closing quote, a short attribution, then a sentence end.
        attribution = re.search(r'[”"][^“”"\n]{1,180}[.!?]$', before.rstrip())
        if attribution and REPORTING_VERBS.search(attribution[0]):
            words = len(attribution[0][1:].split())
            return -1.6 * math.exp(-words / 5.0)
        return 0.0
    if before.endswith('?'):
        if token == '？':
            return -8.2
        if token == '；':
            return -7.2
        if token == '，':
            return -3.0
    if token == '··':
        return -0.66
    if token == '°':
        return -0.15
    if token == '\\n':
        return 0.08
    return -0.004


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (document, (before + token)[-256:]), float(value)

"""A sparse lexical and document-formatting approximation.

The main cues are glass, GitHub host endings, and an opening 'Title:'.
Dictionary meanings supply a few Chinese material and plant-word cues.
Incomplete UTF-8 characters are retained: a prefix narrowing the character
mostly to the jade radical is positive too. Doubled middle dots are negative.
The many smaller, idiosyncratic lexical responses are deliberately omitted.
"""
import codecs
import re
from functools import lru_cache
import regex
import cedict
import unihan

READS = ()
HAN = regex.compile(r'\p{Script=Han}+')


@lru_cache(maxsize=65536)
def chinese_value(text):
    word = text.strip()
    if not HAN.fullmatch(word):
        return 0.0
    meanings = [g.lower().strip() for g in cedict.glosses(word)]
    primary = meanings[0] if meanings else ''
    character_meaning = ''
    if len(word) == 1:
        character_meaning = (unihan.definition(word) or '').lower()
        meanings.append(character_meaning)
    literal = set(meanings)
    value = 0.0
    # Distinguish the material from secondary senses such as a drinking glass.
    if primary == 'glass' or character_meaning == 'glass':
        value += 5.4
    if primary == 'jade':
        value += 2.33
    elif re.search(r'\b(jade|jadeite|jasper|amber|jewelry)\b',
                   '; '.join(meanings)):
        value += 0.4
    if literal.intersection(('apple', 'apples', 'pear', 'pears')):
        value += 2.33
    if literal.intersection(('grape', 'grapes', 'grape wine')):
        value += 2.23
    if re.search(r'\bjasmine\b', '; '.join(meanings)):
        value += 2.15
    if re.search(r'\b(gauze|muslin)\b', '; '.join(meanings)):
        value += 0.55
    return value


@lru_cache(maxsize=1024)
def jade_prefix(pending):
    if len(pending) != 2:
        return 0.0
    # Enumerate the possible final UTF-8 bytes, not a future token.
    count = 0
    for last in range(0x80, 0xc0):
        char = (pending + bytes([last])).decode('utf-8', 'ignore')
        if len(char) == 1 and unihan.radical(char) == 96:  # jade
            count += 1
    return 3.5 * count / 64


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc or carry[2] == '<|endoftext|>':
        age, prev, prev2, pending, tail = 0, '', '', b'', ''
    else:
        _, age, prev, prev2, pending, tail = carry
    raw = prefix.token_strings[-1]
    data = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(data, 'replace', False)
    pending = data[consumed:]
    word = text.strip().lower()
    value = 0.002 + chinese_value(text) + jade_prefix(pending)

    if word == 'glass':
        value += 2.17 if text[0].isspace() else 2.0
    elif word == 'fiberglass':
        value += 1.6
    elif text == 'lass' and prev.lower().endswith('g'):
        value += 1.6
    if text == '··':
        value -= 0.82

    if text == '.com':
        value += 0.05
        if re.search(r'(?<![.\w])github$', tail, re.I):
            value += 1.48
            if prev2.endswith('://'):
                value += 0.56
            if '"' in prev + prev2:
                value += 0.58
    elif text == '.in' and tail.endswith('gopkg'):
        value += 0.9

    if age == 0:
        value += {'//\n': 4.45, '///': 1.3, '<!': 3.95}.get(text, 0.0)
        if re.fullmatch('[A-Za-z]+', text):
            value -= 0.16
        if text == 'package':
            value -= 0.72
    if age == 1 and prev == 'Title' and text == ':':
        value += 5.56
    return (doc, age + 1, raw, prev, pending, (tail + text)[-24:]), value

programs.haiku:
"""Layer 1, MLP down_proj, component 5064: a sparse "glass" feature, with a
weaker pull toward some Chinese fruit and gem names.

Plain-terms summary: this component is silent on almost every token. It fires
on a few specific things:
  - the word "glass" (English, any case; the Chinese word 玻璃 for glass): about +2.2;
  - ".com" right after "github" (github.com links): about +1.9;
  - the colon in a document that opens with "Title:" (the first two tokens of
    a document): about +5.5;
  - weaker, more variable firing on some Chinese fruit and gem names
    (苹果 apple, 葡萄 grape, 梨 pear, 玉 jade, 琼, 珀 amber): about +2 to +3.
Every other token predicts 0.
"""

READS = ()

GLASS_WORDS = {"glass"}
GLASS_CHINESE = {"玻璃", "玻"}
FRUIT_GEM_CHINESE = {"苹果", "葡萄", "梨", "玉", "琼", "珀"}


def doc_position(prefix):
    """Index of the current token inside its own document (0 = first token)."""
    ids = prefix.document_ids
    i = len(ids) - 1
    while i > 0 and ids[i - 1] == ids[-1]:
        i -= 1
    return len(ids) - 1 - i


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    value = 0.0
    if token.lower() in GLASS_WORDS:
        value = 2.2
    elif token in GLASS_CHINESE:
        value = 5.0
    elif token == ".com" and prev.lower() == "github":
        value = 1.9
    elif token == ":" and prev == "Title" and doc_position(prefix) == 1:
        value = 5.5
    elif token in FRUIT_GEM_CHINESE:
        value = 2.0
    return None, value

programs.sol:
"""Estimate dependence and indifference phrases, strongest at their prepositions.

'Regardless of', 'depending on', and 'vary with' give negative pulses.
The pulse often carries into an immediately following 'the' or question word.
Smaller rules cover irrelevance, qualifications, a document-title marker,
and short v/w syllables. These are surface patterns, not a semantic parser.
Only the last 180 characters are retained, separately for each document.
"""
import re
from anyascii import anyascii

READS = ()

# Columns: phrase word, preposition, following 'the', following pronoun/wh-word.
PULSES = {
    'regardless': (-6.2, -18.0, -4.6, -4.8),
    'irrespective': (-6.2, -12.2, -4.3, -3.0),
    'no_matter': (-12.1, 0.0, -5.8, -8.9),
    'depending': (-2.6, -9.6, -6.1, -4.9),
    'depend': (-1.0, -5.2, -3.6, -4.3),
    'dependent': (-0.3, -2.4, -2.4, -2.0),
    'independent': (-0.1, -6.2, -1.7, -2.5),
    'vary': (0.1, -5.6, -2.0, -2.0),
    'covary': (0.0, -6.5, -1.3, -2.0),
    'vary_based': (-4.5, -5.4, -2.5, -3.0),
    'spanish_depending': (-7.0, -4.6, -1.0, -2.0),
    'based': (-0.1, -0.4, -0.2, -0.7),
}
WORDS = re.compile(r'\w+$')
LINKS = {
    'regardless': ('of',), 'irrespective': ('of',),
    'depending': ('on', 'upon'), 'depend': ('on', 'upon'),
    'dependent': ('on', 'upon'), 'independent': ('of',),
    'vary': ('with', 'on', 'as'), 'covary': ('with', 'as'),
    'based': ('on', 'upon'), 'spanish_depending': ('de', 'del'),
}
LINK = re.compile(
    r'\b(regardless|irrespective|depending|depends?|depended|dependent|'
    r'dependence|independent(?:ly)?|var(?:y|ies|ying|ied)|'
    r'(?:increas|decreas|chang)(?:e|es|ed|ing)|grows?|reduces?|declines?|'
    r'dependiendo|depende|dependa|based)\s+'
    r'(?:(?:only|solely|largely|mainly|heavily|strongly|entirely|directly|'
    r'linearly|inversely|monotonically|proportionally|very|much)\s+){0,2}'
    r'(on|upon|of|with|by|as|de|del)\s*$'
)


def family(word):
    if word in ('regardless', 'irrespective'):
        return word
    if word == 'depending':
        return word
    if word.startswith('independent'):
        return 'independent'
    if word in ('dependent', 'dependence'):
        return 'dependent'
    if word in ('depend', 'depends', 'depended'):
        return 'depend'
    if re.fullmatch(r'var(?:y|ies|ying|ied)', word):
        return 'vary'
    if re.fullmatch(r'(?:increas|decreas|chang)(?:e|es|ed|ing)|grows?|reduces?|declines?', word):
        return 'covary'
    if word in ('dependiendo', 'depende', 'dependa'):
        return 'spanish_depending'
    if word == 'based':
        return word
    return None


def valid_link(group, phrase):
    if group == 'covary' and phrase[2] == 'as':
        return phrase[1].startswith(('increas', 'decreas'))
    return phrase[2] in LINKS[group]


def response_class(text, token):
    """A named linguistic condition, rather than a token-identity lookup."""
    if token == ':' and (text == 'Title:' or text.endswith('<|endoftext|>Title:')):
        return 'title_marker'
    if not token or not token[-1].isalpha():
        return None
    tail = text.lower()
    match = WORDS.search(tail)
    word = match[0] if match else token.lower()
    before = tail[:-len(word)].rstrip()
    if word == 'matter' and re.search(r'\bno$', before):
        return 'no_matter', 0
    phrase = LINK.search(tail)
    if phrase:
        group = family(phrase[1])
        # An 'increase of 10%' is a quantity, not a dependence relation.
        if valid_link(group, phrase):
            if group == 'based' and re.search(
                    r'\bvar(?:y|ies|ying|ied)(?:\s+\w+){0,2}'
                    r'\s+based\s+(?:on|upon)$', tail):
                group = 'vary_based'
            return group, 1
    if word in ('the', 'your', 'their', 'how', 'what', 'whether', 'who', 'which', 'when', 'if'):
        if re.search(r'\bno\s+matter$', before):
            return 'no_matter', 2 if word == 'the' else 3
        if re.search(r'\b(?:regardless|depends?|don.t care|not care)$', before):
            return 'indifference_wh'
        phrase = LINK.search(before)
        if phrase:
            group = family(phrase[1])
            if valid_link(group, phrase):
                return group, 2 if word == 'the' else 3
    if word == 'factors' and re.search(r'\bdepend\w*\s+on(?:\s+\w+){0,3}$', before):
        return 'dependence_factors'
    group = family(word)
    if group == 'based' and re.search(r'\bvar(?:y|ies|ying|ied)(?:\s+\w+){0,2}$', before):
        group = 'vary_based'
    if group:
        return group, 0
    if word == 'way' and re.search(r'\b(?:either|whichever)$', before):
        return 'either_way'
    if word in ('matter', 'matters', 'care') and re.search(
            r"\b(?:not|never|doesn.t|don.t|didn.t|wouldn.t|doesnt|dont|didnt)"
            r"(?:\s+(?:it|really|much|even|particularly)){0,2}\s*$", before):
        return 'not_matter'
    if word in ('important', 'difference', 'differences', 'irrelevant', 'immaterial'):
        if word in ('irrelevant', 'immaterial') or re.search(
                r'\b(?:not|no|little|any|much)\s*$', before):
            return 'irrelevant'
    if word == 'noted' and re.search(r'\bbe$', before):
        return 'be_noted'
    if word == 'note' and re.search(r'\bplease$', before):
        return 'please_note'
    if word.endswith('soever'):
        return 'free_choice'
    if word in ('whatever', 'however', 'whenever', 'wherever', 'notwithstanding'):
        return word
    if word in ('what', 'how', 'who', 'whether'):
        return 'wh_word'
    # Dependence/indifference expressions in a few other languages.
    if tail.endswith('independientemente'):
        return 'spanish_independent'
    if tail.endswith('independientemente de'):
        return 'spanish_independent_of'
    if tail.endswith('sin importar'):
        return 'not_matter'
    if re.search(r'\bje nach$', tail):
        return 'german_depending_on'
    if re.search(
            r'\b(?:зависимости|зависит|зависят) от того$', tail):
        return 'russian_depending_complement'
    if re.search(r'\b(?:зависимости|зависит|зависят) от$', tail):
        return 'russian_depending_on'
    if tail.endswith('зависимости'):
        return 'dependent', 0
    if any(tail.endswith(w) or w in token
           for w in ('不管', '无论', '無論', '不论', '不論')):
        if token.endswith('是'):
            return 'chinese_whether_is'
        return 'chinese_regardless'
    if token in ('根据', '不在乎', '取决于'):
        return 'chinese_dependence'
    # A secondary positive response to short vowel + v/w subword syllables.
    syllable = anyascii(token.strip())
    if re.fullmatch('(?:i?e|[ao])[vw]', syllable):
        if 'e' in syllable:
            return 'e_syllable'
        return 'a_syllable' if syllable[0] == 'a' else 'o_syllable'
    if syllable in ('v', 'w') and token == token.strip() and len(text) > len(token):
        if text[-len(token)-1].isalpha():
            return 'v_fragment'
    return None


SMALL = {
    'either_way': -7.5, 'not_matter': -7.0, 'irrelevant': -2.2,
    'indifference_wh': -5.5, 'dependence_factors': -4.7,
    'title_marker': -6.3, 'german_depending_on': -8.1,
    'russian_depending_complement': -7.2,
    'be_noted': -1.9, 'please_note': -1.6,
    'whatever': -1.6, 'however': -0.2, 'whenever': 1.0,
    'wherever': -2.2, 'free_choice': -4.0,
    'notwithstanding': -0.7, 'wh_word': -0.1,
    'spanish_independent': -6.0, 'spanish_independent_of': -5.5,
    'russian_depending_on': -6.0, 'chinese_dependence': -0.7,
    'chinese_regardless': -6.6, 'chinese_whether_is': -0.9,
    'e_syllable': 1.9, 'a_syllable': 0.4, 'o_syllable': 0.1,
    'v_fragment': 0.3,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (previous + token)[-180:]
    condition = response_class(text, token)
    if isinstance(condition, tuple):
        value = PULSES[condition[0]][condition[1]]
    else:
        value = SMALL.get(condition, 0.0)
    return (doc, text), float(value)

"""Approximate a sparse, multilingual local-pattern component.

Large positive rules recognize English modal + focusing adverb, Japanese
auxiliary constructions (especially te/de + iru), Thai go/come and
existence forms, and some Arabic auxiliary forms. Chinese ability/use
expressions get negative values. Most tokens get zero. Strengths are
rounded training estimates; unrelated lexical responses are omitted.
Only the preceding token is retained, resetting between documents.
"""
import re

READS = ()


def activation(previous, token):
    p, s = previous.strip(), token.strip()
    pl, sl = p.lower(), s.lower()
    te_form = p.endswith(('て', 'で'))

    # English: adverbs interrupting a modal/auxiliary and its verb.
    if token.startswith(' '):
        ability = pl in {'can', 'could'}
        modal = pl in {'may', 'might', 'will', 'would', 'shall', 'should', 'must'}
        auxiliary = pl in {'have', 'has', 'had'}
        if sl == 'only':
            if ability:
                return 3.95
            if modal:
                return 1.2
        if sl in {'even', 'ever', 'possibly', 'almost', 'either'} and ability:
            return 1.1
        if sl in {'usually', 'easily', 'often', 'always'} and (ability or modal):
            return -0.3
        if sl == 'all' and (ability or modal or auxiliary):
            return -0.8
        if sl == 'need' and pl == 'will':
            return -0.4
        if sl in {'can', 'could'}:
            return -0.7 if pl == 'how' else 0.08

    # Japanese: split te/de-form + auxiliary, and fused forms of the same.
    # Iru ('be'): its split initial i/ite is especially strong after te/de.
    if s == 'い':
        if te_form:
            return 6.1
        if p.endswith('が'):
            return 1.6
    if s == 'いて':
        if te_form or p in {'に', 'で'} or p.endswith('が'):
            return 6.2
    # Split ki in finishing/coming/going constructions.
    if s == 'き' and p.endswith('り'):
        return 4.0
    if s == 'き' and (te_form or p == 'い'):
        return 8.1
    if te_form and s in {'いた', 'きた', 'いく'}:
        return 4.2
    if s == 'いけ' and p.endswith(('は', 'ば')):
        return 2.1
    if s == 'いる':
        return 2.1
    if re.fullmatch(r'い(?:ます|ました|ません|ない)', s) and te_form:
        return 1.9
    if re.fullmatch(r'(?:て|いて|って|んで)い(?:る|た|ます|ました|ない)', s):
        return 1.5
    if re.fullmatch(r'(?:して|されて|られて)い(?:る|た|ます|ました|く)', s):
        return 1.3
    if te_form:
        # End up/finish (shimau), try (miru), give/help (kureru).
        if re.fullmatch(r'しま(?:う|った|って|います|いました)?', s):
            return 3.0
        if s in {'み', 'みて', 'みる'}:
            return 2.5
        if s in {'くれ', 'くれる', 'くれた'}:
            return 3.4
        # Be/leave (oru/oku), come (kuru), and receive (morau/itadaku).
        if s in {'お', 'おり', 'おります', 'おく', 'おいて'}:
            return 1.9
        if s in {'くる', 'きます', 'きました'}:
            return 2.5
        if s.startswith(('もら', 'いただ', '頂')):
            return 0.8
        if s == 'も':
            return 1.2
    if p == 'い' and s in {'きます', 'きました', 'く'}:
        return 2.0
    if p == 'み' and s == 'た':
        return 3.5

    # Thai: go/come, 'much', and split existential 'have/be' forms.
    if s == 'าก' and p.endswith('ม'):
        return 9.7
    if s in {'ไป', 'มา', 'มาก'}:
        return 9.7
    if s == '่' and p.endswith('ไม'):
        return 2.5
    if s == 'อย':
        return 5.0
    if s == 'ู่' and p.endswith('อย'):
        return 7.0
    if s == 'ม' and p == 'จะ':
        return 7.3
    if s == 'ี' and p.endswith('ม'):
        return 5.8

    # Arabic grammatical verbs: was/is, and completion/passive markers.
    if s == 'تم' and p in {'ي', 'ت'}:
        return 7.0
    if s in {'كان', 'يكون', 'يتم', 'تم'}:
        return 2.8

    # Chinese: capability and the instrumental verbs 'use/adopt'.
    if s in {'能', '能够', '能夠', '可以', '可以用'}:
        return -0.3
    if s in {'使用', '利用', '采用', '採用', '运用', '運用'}:
        if p in {'需', '需要', '无需', '無需', '必须', '必須'}:
            return -2.8
        if p in {'如何', '怎么', '怎麼', '请', '請', '通过', '通過'}:
            return -2.0
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = activation(previous, token)
    return (document, token), value

programs.haiku:
