"""Approximate a local rhotic spelling response, not a semantic category.

Across adjacent word pieces, r followed by i usually gives a negative value,
strongest before t, s, or z. Selected vowel combinations and er continuations
are positive. The strength depends on spelling, piece length, and the letter
before r. There are also negative rules for arith- and short consonant-a/e/o-
r-i-s/t/z openings, including doubled r.

Transliteration applies these rules across alphabets, excluding Han/Hangul.
An uppercase piece after lowercase is treated as a new code-name segment.
The end-of-text marker has its own negative value. Only the previous token is
remembered, with a reset between documents. Lexical exceptions are omitted.
"""
from anyascii import anyascii
import regex
import re

READS = ()
VOWELS = 'aeiou'


def continuation(s):
    """The strength of an unspaced continuation after r."""
    n = len(s)
    if s == 'i':
        return -1.0
    if s.startswith('ith'):
        return -6.0 if n <= 3 else -2.0
    if s.startswith('it'):
        return -4.3 if n == 2 else -2.4 if n <= 4 else -0.5
    if s.startswith(('is', 'iz')):
        if n == 2:
            return -3.7
        if n == 3:
            return -2.8 if s[1] == 'z' else -2.2
        if n == 4:
            return -1.3
        return -0.6 if n == 5 else -1.4
    if s.startswith('id'):
        return -2.1 if n == 2 else -1.2 if n == 3 else -0.9
    if s.startswith('ia'):
        return 1.4 if n == 2 else 0.8 if n <= 4 else 0.0
    if s.startswith(('ie', 'iu', 'ii')):
        return 0.6 if n <= 4 else 0.0
    if s.startswith('in'):
        return 0.1 if n <= 3 else 0.0
    if s.startswith('i') and n > 1 and s[1].isalpha():
        return -1.0 / (1.0 + 0.5 * (n - 2))
    if s.startswith('er'):
        return 0.3 if n == 2 else 0.9 if n == 3 else 0.0
    return 0.0


def response(previous, current):
    if current == '<|endoftext|>':
        return -1.15
    if regex.search(r'[\p{Han}\p{Hangul}]', previous + current):
        return 0.0
    if current.isupper() and len(current) > 1 and previous[-1:].islower():
        return 0.0
    p = anyascii(previous).lower()
    c = anyascii(current).lower()
    word = c.strip()
    if word.startswith("arith"):
        return -2.7
    short_rhotic = r"^[bcdfghjklmnpqrstvwxyz][aeo]rr?i[stz]"
    if len(word) <= 6 and re.match(short_rhotic, word):
        return -1.7
    if p.endswith('r'):
        strong = len(p) > 1 and p[-2] in VOWELS
        if strong:
            gain = 1.0
        elif p.endswith('rr') or p.strip() == 'r':
            gain = 0.8
        else:
            gain = 0.15
        return gain * continuation(c)
    if c.startswith('ri') and p[-1:] in tuple(VOWELS):
        return -0.17 if c == 'ri' else 1.1 * continuation(c[1:])
    # Japanese syllabic spelling can put the i in the preceding token.
    if previous == 'リ' and c.startswith(('t', 's', 'z')):
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    current = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, current), response(previous, current)

