    'all right': -3.2,
    'all in': -1.5,
    'all over': -0.95,
    'off of': -3.0,
    'in mind': -1.1,
    'to mind': 2.0,
    'in spite': -2.2,
    'so doing': -3.7,
    'some reason': 3.0,
