"""Explains layers.1.mlp.down_proj:5071 with a few word lists and one context rule.

The component is a bidirectional "offence" vs "manner" direction in the residual stream:

* Positive on words meaning offence or transgression: "offense", "offended",
  "offensive", "offender", and the same idea in other scripts: 犯 (commit a
  crime / offend), 冒 and 得罪 (give offence), 侵犯 (violate), phạm (commit an
  offence). The biggest values are on 犯 and phạm.
* Negative on a manner or reason noun that closes a demonstrative phrase:
  "in this way", "for this reason", "this type", "that kind", "each case".
  "in this way" and "for this reason" are the strongest cases.
* Negative on "case(s)" after each / any / all / some / many, and mildly negative
  on a pronoun after "of" ("most of which", "each of them").
* Mildly positive on "way", "reason" after any / some / every ("any way").

Everything else is 0. The program is stateless: it reads only the newest token and
the one before it, within the same document.

Main program: `step` below. Weights are rounded least-squares fits on about
4,000 training rows.
"""

READS = ()

OFFENCE_STEMS = ("offen", "offend", "offence")
OFFENCE_CHARS = {"犯", "冒", "得罪", "侵犯", "phạm"}
MANNER_NOUNS = {"way", "reason", "manner", "type", "kind", "sort", "form"}
DEMONSTRATIVES = {"this", "that", "such", "each", "either", "these", "those"}
QUANTIFIERS_ANY = {"any", "some", "every", "whatever"}
CASE_QUANTIFIERS = {"each", "any", "every", "all", "some", "many", "most", "both", "other"}
OBJECT_PRONOUNS = {"them", "which", "it", "whom"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if word.startswith(OFFENCE_STEMS) or prefix.token_strings[-1].strip() in OFFENCE_CHARS:
        return carry, 4.0 if word.startswith(OFFENCE_STEMS) else 6.0
    if word in MANNER_NOUNS and before in DEMONSTRATIVES:
        return carry, -3.0
    if word in MANNER_NOUNS and before in QUANTIFIERS_ANY:
        return carry, 1.0
    if word in {"case", "cases"} and before in CASE_QUANTIFIERS:
        return carry, -2.4
    if word in OBJECT_PRONOUNS and before == "of":
        return carry, -0.5
    return carry, 0.0

