    if n == 1 or docs[-1] != docs[-2]:
        return carry, 0.4
    p1 = toks[-2]
    p2 = toks[-3] if n >= 3 and docs[-3] == docs[-1] else ""
    if cur in SUBJ and p1 in LET:
        return carry, -1.1
    if p2 in LET and p1 in SUBJ:
        return carry, -2.0 if cur in EXAMINE else -1.0
    if cur in PREPS and p1 in RETURN_WORDS:
        return carry, -1.5 if p1 in (" Back", "Back", " back", " returning", " Returning") else -0.8
    if cur in OPENERS:
        return carry, OPENERS[cur]
    return carry, 0.0

