"""An approximate detector of short Indonesian word beginnings.

Recent function words and Indonesian-versus-European word frequencies establish
language context. In that context, exposed ber-, ter-, per-, meN-, peN-, ke-
and se- prefixes have negative values. A prefix may span tokens; other fragments
get weaker or zero values. Three additional rules handle initial 'Title:', repeated
middle-dot filler, and Persian بر. The model's weak background responses are
not reproduced. Word and language state reset at every document boundary.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
FUNCTION_WORDS = set('''yang dengan tidak untuk dalam adalah tersebut kepada
karena mereka sebagai bahwa sudah menjadi hanya bukan belum kita saya anda
bisa akan pada dari oleh juga serta agar yaitu maka harus lebih sangat
atau setelah seperti tentang antara dapat telah tanpa ketika hingga'''.split())

# Productive affixes, ordered with longer nasal variants before me- and pe-.
AFFIXES = {
    'ber': -8.0, 'ter': -5.7, 'per': -4.9,
    'meng': -4.1, 'meny': -4.1, 'mem': -4.9, 'men': -4.9,
    'pem': -2.8, 'pen': -2.8, 'me': -2.0, 'pe': -3.1,
    'ke': -4.7, 'se': -5.4,
}


def fragment_value(word, starts, previous):
    # Recover an affix whose first consonant was a separate token.
    if not starts and previous in ('k', 's'):
        if word.startswith(previous + 'e'):
            return -5.2 if previous == 'k' else -4.3
    if not starts and previous in ('b', 't', 'p', 'm'):
        if word.startswith(previous + 'e'):
            word = word[:4]
    if word.startswith('keter') and len(word) <= 5:
        return -8.3
    if word == 'member':  # unfinished memberi, "give"
        return -4.9
    for affix, value in AFFIXES.items():
        limit = 3 if affix in ('ke', 'se') else 4
        if word.startswith(affix) and len(word) <= limit:
            return value
    if len(word) == 1 and word.isalpha():
        initials = {'m': -3.1, 'p': -2.2, 'k': -1.7}
        return initials.get(word, 0.3 if word in 'aeiou' else -1.0)
    return 0.1 if starts else 0.0


@lru_cache(maxsize=40000)
def language_evidence(word):
    if word in FUNCTION_WORDS:
        return 1.0
    if len(word) < 4:
        return 0.0
    indonesian = zipf_frequency(word, 'id')
    foreign = max(zipf_frequency(word, lang)
                  for lang in ('en', 'de', 'es', 'fr', 'it', 'pt', 'nl'))
    if indonesian >= 4.0 and indonesian >= foreign + 0.8:
        return 0.8
    if foreign >= 5.0 and foreign >= indonesian + 1.5:
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, '', 0)
    _, word, evidence, previous_token, position = carry
    text = prefix.token_strings[-1]
    previous_word = word
    starts = not word or not text[:1].isalpha()
    for piece in re.findall(r'[A-Za-z]+|[^A-Za-z]+', text):
        if piece.isascii() and piece.isalpha():
            word = (word + piece.lower())[-40:]
        else:
            if word:
                evidence = max(0.0, 0.90 * evidence + language_evidence(word))
                if evidence > 0.5 and word in ('dan', 'di', 'ini', 'itu'):
                    evidence += 0.3
            word = ''
    confidence = min(1.0, max(0.0, (evidence - 0.75) / 0.5))
    value = confidence * fragment_value(word, starts, previous_word) if word else 0.0
    if text == ':' and previous_token == 'Title' and position == 1:
        value = 18.42
    elif text == '··' and (position == 0 or previous_token == '··'):
        value = -2.28
    elif text == ' بر':
        value = -1.2
    return (doc, word, evidence, text, position + 1), value

