"""Layer-1 MLP component 5074: a detector for word-start prefixes in Indonesian text.

What it does: on a token that is a bound prefix fragment of an Indonesian verb or
noun (ber-, ter-, meng-, mem-, men-, peng-, pem-, bers-, ...), such as "ber" in
"berlaku", "meng" in "mengangis", "se" in "sehari", it goes negative, but only
when the document so far reads as Indonesian. Indonesian is judged from how many of
its tokens are common Indonesian function words (yang, dengan, tidak, ...). The
fragment is only part of a word, so the model is holding an unfinished word open.
The same strings in English, German, Italian or code do almost nothing.

A rare, very large case is also handled: a document that opens with "Title:"
(the token "Title" first, then a colon) gets a large positive value on the colon.
"""

READS = ()

# Bound prefixes that begin Indonesian words, with the typical size of their dip.
# meN- (meng-, mem-, men-, ...) and ber- are the strongest; per-, se-, ke- weaker.
STRONG_BER = {"ber": -5.0, "Ber": -5.0, "bers": -8.0, "bert": -8.0}
MENG_GROUP = {"meng", "mem", "men", "meny", "mend", "memb", "menc", "mel", "pem", "peng",
              "pen", "pend", "kem", "sel", "pel"}
TER_GROUP = {"ter", "tert", "pert"}
WEAK_GROUP = {"se", "ser", "ses", "ke", "kes", "per"}

# Common Indonesian function words, used to judge whether a document is Indonesian.
INDONESIAN_WORDS = set("""
yang dengan untuk dari tidak adalah akan pada atau dalam saya bisa juga sudah belum
oleh karena tersebut kami kita mereka bagi agar serta sebagai dapat harus lebih secara
telah hanya tentang kepada jika bahwa sangat banyak ia anda bagaimana sehingga namun
pun lagi hingga setelah saat kini masih baru bukan kalau seperti semua setiap mau tapi
orang saja ini itu
""".split())


def prefix_value(word):
    if word in STRONG_BER:
        return STRONG_BER[word]
    if word in MENG_GROUP:
        return -4.0
    if word in TER_GROUP:
        return -3.0
    if word in WEAK_GROUP:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = prefix.token_strings[-1].strip().lower()
    if carry is None or carry[0] != doc:
        # a new document: its token count, Indonesian-word count and first token restart
        n_before, n_indonesian, first = 0, 0, None
    else:
        _, n_before, n_indonesian, first = carry

    if n_before == 1 and first == "title" and word == ":":
        value = 18.4
    elif n_indonesian >= 3 and n_indonesian >= 0.05 * n_before:
        value = prefix_value(word)
    else:
        value = 0.0

    if first is None:
        first = word
    if word in INDONESIAN_WORDS:
        n_indonesian += 1
    return (doc, n_before + 1, n_indonesian, first), value

