            if text.isascii() or ALPHABET.search(text) else text)


def predict(text, previous, previous_value, first):
    s = spelling(text)
    w = s.strip()
    cyrillic = bool(CYRILLIC.search(text))
    joined = bool(s and s[0].isalpha() and previous
                  and previous[-1].isalpha())
    value = 0.0
