    if w in ('of', '_of', '-of'):
        last = re.search(r'([a-z]+)$', previous)
        last = last.group(1) if last else ''
        if last in ('exponent', 'ponents', 'ponent'):
            return 3.7
        if last in ('power', 'powers'):
            return 2.7 if last == 'power' else 3.8
        if last in ('multiple', 'multiples'):
            return 0.95 if last == 'multiple' else 2.4
        if 'pol' in last or last == 'roll':
            return -0.8
