    elif w.startswith('pol') and len(w) <= 6:
        ending = w[3:]
        if ending in ('l', 'o'):
            value = -3.5
        elif ending == 'e':
            value = -1.4
        elif ending == 'ar':
            value = -0.65
        else:
            value = -1.9
    elif 'pol' in w and len(w) <= 5:
        value = -3.5
    elif w.startswith('pol'):
        value = -0.15
    elif cyrillic and w.startswith('po') and len(w) == 3:
        value = -1.3
    elif w in ('paul', 'pool', 'pul'):
