            elif s.startswith('oll') and len(s) <= 4:
                value = -8.0
            else:
                value *= exp(-0.65 * max(0, len(s) - 2))
        elif previous.endswith('po') and s.startswith('l'):
            value = -8.0 * exp(-0.7 * (len(s) - 1))
        elif previous.endswith('p') and s.startswith('ound'):
            value = 7.8 if len(previous.strip()) <= 2 else 0.0
        elif previous.endswith('pop') and s.startswith('ul'):
            value = -8.0 * exp(-0.35 * max(0, len(s) - 5))
        elif previous.endswith('p') and s.startswith('ul'):
            value = -2.8
        elif previous.endswith('pol'):
            persistence = 0.8 if s in ('i', 'is', 'an') else 0.25
            value += persistence * previous_value / max(1.0, len(s) / 2)
    return value


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, previous_value = ('', 0.0) if first else carry[1:]
    text = prefix.token_strings[-1]
    value = predict(text, previous, previous_value, first)
