        # Continuations of a partly spelled metre/metric stem.
        if before.endswith('met'):
            if piece.startswith('rical'):
                return 1.7
            if piece == 'r':
                return 5.3
            if piece in ('re', 'res', 'ern'):
                return 5.1
            if piece in ('ri', 'rie', 'ries', 'rik', 'ric', 'rio', 'rid'):
                return 9.2 if re.search(r'\p{Script=Cyrillic}', original) else 2.6
            if piece in ('ra', 'ram', 'rov', 'ry'):
                return 1.1 if 'paramet' in word else 5.1
            if piece in ('ro', 'ros'):
