            if piece == 'et':
                return 3.0 if before.endswith(('om', 'im')) else 1.7
            if piece.startswith(('eter', 'etre', 'etro', 'etry')):
                return 5.4
            if piece.startswith('etric'):
                return 0.6 if before.endswith('param') else 2.4
            if piece.startswith('etr'):
