    if word in ('metric', 'metrics', 'metrical'):
        return 1.1
    if word.endswith(('meter', 'meters')):
        if not word.startswith(('para', 'dia', 'kilo', 'milli', 'centi', 'nano', 'micro')):
            return 0.9
    if word in ('symmetric', 'geometric'):
