    'di che non una il gli le si per del della delle nella questo sono come '
    'que puede poder los las el un se para por con um uma não você'.split())
PERSONAL = set('i we you he she they me us him her them'.split())
INDEFINITE_PEOPLE = set(
    'people one anyone anybody someone somebody everyone everybody human humans'.split())
SUBJECT_OFFSET = {
    'i': -3.90, 'we': -3.59, 'you': -3.47, 'he': -3.27, 'she': -3.27,
    'they': -1.97, 'who': -1.97, 'it': -.45, 'which': .27,
    'this': .17, 'that': .17, 'these': .17, 'those': .17,
}
ABILITY_ADJECTIVES = {
