"""Layer 1, MLP down-projection, component 5085: a single letter used as a maths symbol.

What it responds to: a standalone one-letter token (x, y, z, f, k, u, q, ...) that is a
variable or function name in mathematics, as in "so [x]=0", "What is [q](-3)?",
"Let [z]...". It stays near zero for the same letters inside a word ("appoint[s]"),
for the article "a" and the pronoun "I" in ordinary prose, and for digits.

The rule below predicts its activation:
  * a standalone letter (it starts a word or follows a symbol, rather than continuing a
    word) scores 0.5 * (share of maths-like tokens earlier in the document + 0.2);
    doubled if it follows a word or symbol that introduces a variable ("so", "Let",
    "where", "$", "=", "("), and doubled again if it is a common variable name;
  * a maths function name (sqrt, log, sin, cos, tan, ln, frac, lim) scores
    0.5 * (the same maths share + 0.2);
  * the first token of a document scores 0.4, its typical value;
  * everything else scores 0.

It reads only the tokens so far, and resets at each document boundary.
"""

import re

READS = ()

LETTER = re.compile(r" ?[A-Za-z]")
ENDS_IN_WORD = re.compile(r"[A-Za-z0-9]$")
MATHY = re.compile(r"[0-9=+\-*/^()\[\]$\\{}<>|]")
INTRO = {" so", " Let", "Let", " where", " $", " $$", ":\n\n", " if", " when", " that",
         " since", " then", " is", " =", "=", ")=", " ("}
VARIABLES = set("xyzukfhqrtspnm")
FUNCTIONS = {"sqrt", "log", "sin", "cos", "tan", "ln", "frac", "lim"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "prev": "", "maths": 0, "count": 0}
    prev, count = carry["prev"], carry["count"]
    share = (carry["maths"] / count if count else 0.0) + 0.2
    word = token.strip(" ")
    if count == 0:
        value = 0.4
    elif LETTER.fullmatch(token) and (token.startswith(" ") or not ENDS_IN_WORD.search(prev)):
        value = 0.5 * share * (2 if prev in INTRO else 1) * (2 if word in VARIABLES else 1)
    elif word in FUNCTIONS:
        value = 0.5 * share
    else:
        value = 0.0
    new = {
        "doc": doc,
        "prev": token,
        "maths": carry["maths"] + (MATHY.search(token) is not None),
        "count": count + 1,
    }
    return new, float(value)

