    if s in {'or', 'y', 'e', 'und', 'en', 've', 'и', 'و', 'och', 'og'}:
        return 'join'
    if s.lower() in {'jr', 'sr', 'ed', 'eds', 'editor', 'admin', 'author'}:
        return 'suffix'
    if s.startswith('.') and not s.startswith('..'):
