CODE_MARKS = set('{["\'_=(')
CAUSE = {' because', ' due', ' via', ' using', ' by', ' through', ' based'}
QUANTITY = {' two', ' three', ' four', ' five', ' several', ' both', ' either', ' between'}
RELATIVE = {' which', ' who', ' that', ' where', ' whom', ' whose', ' including'}


