    tok = prefix.token_strings[-1]
    p = prefix.position
    if p == 0:
        value = 0.15
    elif tok in KEY_COLONS:
        value = 0.7
    elif tok == ':':
        recent = ''.join(prefix.token_strings[max(0, p - 6):p])
