"""layers.1.mlp.down_proj:5097 -- a token-trigger detector, written as a short rule list.

What the component does. Its activation is mostly quiet (near 0) and is large on a few
recognisable patterns. The clearest ones:

* the word right after "as" when it starts a legal or technical stock phrase: "as amended",
  "as defined", "as provided", "as compared", "as a whole", "as any", "as $" -> negative;
  "as part (of)" -> positive;
* "AS IS" (the licence phrase) -> strongly negative on "IS";
* "using System" / "using namespace" (C#/C++ headers) -> negative on the second word;
* "&mut" (Rust) -> negative on "mut"; "\\begin{aligned" -> positive on "aligned";
* a run of middle-dot leaders "··" -> negative;
* the colon in "Title:" that opens a document -> strongly positive (rare, but very large);
* the first token of a document (the start of a packed row or after <|endoftext|>) is
  mildly negative, as is typical of a token with no left context.

The program below predicts those values and 0 everywhere else. It needs only the current
token and the one before it, plus whether that token opens a document.
"""

READS = ()

DOC_START = -0.3  # first token of a document: mildly negative on average

# words that follow "as" in legal and technical boilerplate
AS_NEGATIVE = {" amended", " defined", " provided", " specified", " determined", " required",
               " modified", " compared", " applied", " described", " set", " taught", " expressly",
               " whole", " any", " $", " between", " at", " already", " more"}
AS_POSITIVE = {" part", " possible", " follows"}  # "as part of", "as possible", "as follows"

# fixed two-token phrases: (previous token, this token) -> activation
PHRASES = {
    ("using", " System"): -1.5,
    ("using", " namespace"): -1.4,
    ("AS", " IS"): -2.7,
    ("as", " IS"): -2.7,
    ("&", "mut"): -0.8,
    ("{", "aligned"): 1.2,
}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    if len(tokens) == 1:  # first token of a packed row
        return carry, DOC_START
    prev = tokens[-2]
    if cur == "··":  # middle-dot leader run
        return carry, -1.2
    if prev == "<|endoftext|>":  # first token of a later document
        return carry, DOC_START
    if cur == ":" and prev == "Title" and len(tokens) >= 3 and tokens[-3] == "<|endoftext|>":
        return carry, 6.9  # "Title:" opening a document
    if prev in (" as", " As", "as", "As"):
        if cur in AS_NEGATIVE:
            return carry, -1.3
    if prev in (" as", " As") and cur in AS_POSITIVE:
        return carry, 1.0
    return carry, PHRASES.get((prev, cur), 0.0)

