from collections import defaultdict
from functools import lru_cache
import wordfreq
import cedict
import wordnet
import regex

READS = ()
SUBJECTS = set('''i you he she it we they who which that this these those
je tu il elle nous vous ils elles on ich du er sie es wir ihr
 yo tú él ella nosotros vosotros ellos ellas usted ustedes
 io lui lei noi voi loro eu ele ela nós vós eles elas você vocês
 я ты он она оно мы вы они кто'''.split())
MODALS = set('''to can could will would shall should must may might
peut peux peuvent pourrait doit dois doivent kann kannst können konnte
müssen muss soll sollte wird werden würde puede pueden podría debe deben
può possono deve devono pode podem могу может могут должен должна должны
можно нужно sẽ'''.split())
PARTICIPLES = set('''am is are was were be been being have has had
est sont suis êtes était ont avez avoir être ist sind war waren hat haben
été es está están son foi são были был была есть'''.split())
NEGATION = {'not', 'never', "n't", 'n’t'}
EN_SUBJECTS = set('i you he she it we they who which that'.split())
EN_FUNCTIONS = set('''a an the my your his her its our their some any each every
this these those i you he she it we they who which that can could will would
shall should must may might am is are was were be been being have has had
do does did to of in on at by for from with without into about as than over
under through during before after between among and or but not never'''.split())

@lru_cache(maxsize=50000)
def parts(word):
    return wordnet.parts_of_speech(word.lower())

# Frequency mass of longer words sharing each spelling prefix.
EN_PREFIX = defaultdict(float)
for word in wordfreq.top_n_list('en', 60000):
    if word.isalpha():
        mass = 10 ** (wordfreq.zipf_frequency(word, 'en') - 5)
        for n in range(1, min(9, len(word))):
            EN_PREFIX[word[:n]] += mass

PREFIX, WHOLE = defaultdict(float), defaultdict(float)
for language in ('en', 'de', 'fr', 'es', 'it', 'pt', 'nl', 'ru', 'zh', 'vi'):
    frequencies = wordfreq.get_frequency_dict(language)
    for word in wordfreq.top_n_list(language, 40000):
        if word.isalpha():
            mass = frequencies.get(word, 0.) * 10000
            WHOLE[word] += mass
            for n in range(1, min(9, len(word))):
                PREFIX[word[:n]] += mass

@lru_cache(maxsize=50000)
def completeness(word):
    word = word.lower()
    rest, own = PREFIX.get(word, 0.), WHOLE.get(word, 0.)
    fragment = rest / (rest + own + .001)
    frequency = wordfreq.zipf_frequency(word, 'en') if word.isalpha() else 0.
    own_en = 10 ** (frequency - 5) if frequency else 0.
    rest_en = EN_PREFIX.get(word, 0.)
    english_fragment = rest_en / (rest_en + own_en + .001)
    return fragment, frequency, english_fragment

@lru_cache(maxsize=30000)
def chinese_verb(word):
    if not regex.search(r'\p{Script=Han}', word):
        return False
    glosses = cedict.glosses(word)
    verbs = sum(bool(re.search(r'(^|\) )to ', g)) for g in glosses)
    return verbs / max(1, len(glosses)) > .01

def grammatical_slot(word):
    word = word.lower()
    if word in SUBJECTS:
        return 'subject'
    if word in MODALS:
        return 'infinitive'
    if word in PARTICIPLES:
        return 'participle'
    return 'other'

def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, True, '', '', 'other', 0)
