    _, first, running, preceding, slot, prose = carry
    onset = bool(token) and (not token[0].isalpha() or not running)
    letters = re.findall(r'[^\W\d_]+', token)
    if onset:
        previous = running or preceding
        if running and running.lower() in EN_FUNCTIONS:
            prose = min(6, prose + 1)
        new_slot = grammatical_slot(previous)
        if previous.lower() not in NEGATION:
            slot = new_slot
        preceding = previous
        word = letters[-1] if letters else ''
    else:
        word = running + (letters[0] if letters else '')
    context = slot
    if token in {"n't", "'t", '’t'}:
        word = 'not'
        slot = slot if slot in {'infinitive', 'participle'} else 'infinitive'
    running = word[-60:] if token and token[-1].isalpha() else ''
    if word and not running:
        preceding = word
    if any(c in token for c in '{}_=\\'):
        prose = max(0, prose - 3)
    carry = (doc, False, running, preceding, slot, prose)

    w = token.strip()
    capital = bool(w) and w[0].isupper()
    if first:
        if not w.isalpha():
            if token.startswith('<|') or token in {'<think>', '</think>'}:
                return carry, -.079
            return carry, .159 if len(w) <= 2 else .421
        if len(w) == 1:
            return carry, .122 if capital else .415
        common = wordfreq.zipf_frequency(w.lower(), 'en') > 5.4
        return carry, .389 if common else .511

    multilingual_fragment, frequency, english_fragment = completeness(w)
    fragment = english_fragment if prose else multilingual_fragment
    if fragment <= .9:
        return carry, -.087 if w.lower() == 'no' else -.003
    if onset and context == 'subject':
        if capital:
            return carry, -.018
        if previous.lower() not in EN_SUBJECTS:
            return carry, -.119
        if prose < 6:
            return carry, -.266
        if 'verb' in parts(w):
            return carry, -.179
        return carry, -.251 if len(w) <= 1 else -.761
    if onset and context == 'infinitive':
        if capital:
            return carry, -.033
        if 'verb' in parts(w):
            return carry, -.108
        if len(w) <= 1:
            return carry, -.135
        return carry, -.362 if frequency <= 3. else -.802
    if not token.startswith(' '):
        return carry, -.077 if chinese_verb(w) else .001
    if onset and context == 'participle':
        return carry, -.026 if capital else -.257
    return carry, -.011 if capital or len(w) <= 2 else -.069

"""Source-code declaration cues, especially class-qualified method boundaries.

Predict negative pulses at C++ method scopes and overload declarations, Go
receiver endings, inheritance markers, Java getter names, and JavaScript
prototypes.  Quoted C/C++ headers are another negative cue.  Ordinary scope
resolution is mildly positive; most other text is near zero.  These are text
heuristics, not a complete parser. A colon after an initial "Title" label is
also positive. Only a 256-character document-local tail is kept; amplitudes
are rounded means from training examples. Unrecognized text is near zero.
