import re

READS = ()
CUES = {
    ')', 'extends', 'implements', 'struct', ':', 'get', '#get',
    '::', '::_', '::~', '>::', 'operator', '.prototype', '.h', '.hpp',
}
CPP_TYPE = (
    r'(?:void|bool|int|double|float|char|auto|struct|long|short|unsigned|'
    r'[A-Z]\w*|[a-z]\d\w*|[a-z]\w*_t|std::\w+|[io]+stream)'
    r'(?:<[^;{}()]*>)?'
)
CLASS_NAME = r'(?:[A-Z_]+\s+)?\w+(?:<[^;{}\n]*>)?\s*$'


def activation(token, before):
    """Approximate pulses at familiar source-code syntax boundaries."""
    s = token.strip()
    if s == ':' and before == 'Title':
        return 4.28
    if s not in CUES:
        return -0.0007
    # Code also occurs inside JSON strings with escaped newlines and tabs.
    before = before.replace('\\n', '\n').replace('\\t', '\t')
    line = before.rsplit('\n', 1)[-1]
    if s == ')':
        if re.search(r'\bfunc\s+\(\s*\w+\s+\*?[\w.]+'
                     r'(?:\[[^\]]*\])?\s*$', before):
            return -4.81
        if re.search(r'\bfunc\s+[^{};\n]{0,160}\([^()]*$', before):
            return -0.79
    if s in ('extends', 'implements'):
        if re.search(r'\b(class|interface)\s+[A-Z]\w*(?:<[^;{}]*>)?\s*$', before):
            if s == 'implements':
                return -1.24
            if re.search(r'\b(public|protected)\b', line):
                return -6.09
            return -3.66
    if s == 'struct' and re.search(r'\btype\s+\w+\s*$', before):
        return -1.19
    if s == ':' and '\n' not in token and re.search(
        r'\b(class|struct|interface)\s+' + CLASS_NAME, before
    ):
        if re.search(r'\bpublic\b', line):
            return -6.57
        return -3.66
    if s == 'get':
        java_type = (r'(?:[a-z]\w*\.)*(?:[A-Z]\w*|boolean|int|long|double|float)'
                     r'(?:<[^;{}()]*>|\[\])?')
        code_context = re.search(r'[;{}@]|\*/|\b(import|class|interface)\b', before)
        modifiers = r'(?:(?:public|private|protected|static|final)\s+)*'
        if code_context and re.fullmatch(
            r'[ \t\d+\-]*' + modifiers + java_type + r'\s*', line
        ):
            return -1.57
    if s == '#get':
        return -4.67
    if s == '.prototype':
        return -5.12
    if s in ('.h', '.hpp'):
        if re.search(r'#\s*include\s*"[^"<>\n]*$', before):
            return -2.12
    if s in ('::', '::_', '::~', '>::'):
        rust = re.search(
            r'\bfn\s+\w+\s*[<(]|\blet\s+\w+(?:::|\s*=)|\.rs\b', before
        )
        php = re.search(r'\$|<\?php|\bfunction\b', before)
        if rust or php:
            return 0.45
        if token[:1].isspace() or re.search(r'\bstd$', line):
            return 0.45
        declaration = re.sub(r'^.*@fn\s+|^\s*//\s*', '', line)
        modifiers = r'(?:(?:inline|static|virtual|const|[A-Z_]{3,})\s+)*'
        if re.fullmatch(r'[\s\d+\-]*' + modifiers + CPP_TYPE
                        + r'\s*[*&]*[ \t]+[\w:]+', declaration):
            return -10.67
        if re.search(r'\b(?:void|bool|int|double|float)\s*\n\s*\w+$', before):
            return -10.67
        pointer_tail = before + ('>' if s == '>::' else '')
        if re.search(r'&\s*\w+(?:<[^>]*>)?$', pointer_tail):
            return -2.47
        if re.fullmatch(r'\s*(?:inline\s+)?[A-Z]\w*', line):
            cpp = re.search(r'#include|\binline\b|};?\s*\n\s*\n', before)
            php = re.search(r'\bfunction\b|\$|<\?php', before)
            if cpp and not php and not re.search(r'{\s*\w+$', before):
                return -6.49
        return 0.45
    if s == 'operator':
        if before.endswith('::'):
            return -5.54
        if re.fullmatch(r'[ \t\d+\-]*(?:(?:virtual|friend|inline|static|const)\s+)*'
                        + CPP_TYPE + r'\s*[*&]*\s*', line):
            return -5.54
    return -0.0007


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, before)
    return (doc, (before + token)[-256:]), value

"""A lexical pulse at the beginning of a document, not a topic detector.

Estimate the first visible token from spelling and familiar grammatical/code
categories; predict nearly zero afterwards. These coarse categories omit
token-specific variation and exceptional repeated-token runs.
"""
import unicodedata

READS = ()

LOW_CONTENT_WORDS = set('''
    a an i you he she we they me him her us them my your his our their
    mine yours ours theirs myself yourself himself herself itself ourselves
    themselves am is are was were be been being have has had do does did
    can could shall should will would may might must of in on at to for
    from by with as about into through over under between after before
    without within against among
'''.split())
CONJUNCTIONS = set('''
    and or but if because while although since unless than whether
'''.split())
DECLARATIONS = set('''
    package class interface enum struct typedef public private protected
    def function namespace using include define ifndef
'''.split())


def initial_value(text):
    word = text.strip()
    lower = word.lower()
    if not word:
        if text == '\r':
            return 10.0
        if '\t' in text:
            return 6.4 if text == '\t' else 4.0
        if '\n' in text or '\r' in text:
            return -0.3
        return -0.5 if len(text) == 1 else 2.3
    if word.startswith('<|'):
        return 3.65
    if word.isdecimal():
        return -0.45
    names = [unicodedata.name(c, '') for c in word]
    if any('CJK' in name for name in names):
        return 0.1
    if any('CYRILLIC' in name for name in names):
        return -0.65
    if not word.isascii():
        return 1.25
    if text == 'import':
        return 14.5
    if lower in DECLARATIONS:
        return 6.0
    if lower == 'the':
        return 3.45
    if lower == 'it':
        return 5.2
    if lower in LOW_CONTENT_WORDS:
        return 0.2
    if lower in CONJUNCTIONS:
        return 0.8
    if lower in {'this', 'that', 'these', 'those'}:
        return 1.3
    if lower in {'who', 'what', 'which', 'where', 'when', 'why', 'how'}:
        return 2.1
    if not any(c.isalnum() for c in word):
        return 0.8 if len(word) == 1 else 2.4
    if not word.isalpha():
        return 3.8
    return 1.9 if word.istitle() and not text[0].isspace() else 2.2


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry != document:
        return document, initial_value(prefix.token_strings[-1])
    return document, -0.0017

"""Approximate a productive-prefix signal in unfinished words.

An attached re-, un-, de-, etc. is strongest when its remainder looks like
an independently familiar word or the beginning of an action word. Common
whole spellings are weaker than unusual, compositionally spelled ones.
Frequency and dictionary rules are fixed linguistic resources, not token IDs.
This spelling heuristic misses some whole-token and non-Latin responses.
The carry tracks only the unfinished word and resets between documents.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency, top_n_list

READS = ()
AFFIXES = ('under', 'trans', 'over', 'down', 'mis', 'pre', 'dis',
           'out', 'sub', 'con', 're', 'de', 'un', 'up', 'in')
LETTERS = re.compile('[A-Za-z]+')

# How familiar an unfinished action word can be: e.g. "organiz" -> "organize".
ACTION_STARTS = {}
for word in top_n_list('en', 50000):
    if not word.isalpha():
        continue
    if ('verb' not in wordnet.parts_of_speech(word)
            and 'noun.act' not in wordnet.categories(word)):
        continue
    freq = zipf_frequency(word, 'en')
    for length in range(3, len(word) + 1):
        start = word[:length]
        ACTION_STARTS[start] = max(ACTION_STARTS.get(start, 0.), freq)

@lru_cache(maxsize=150000)
def word_features(word):
    affix = next((p for p in AFFIXES
                  if word.startswith(p) and len(word) > len(p)), None)
    if affix is None:
        return None
    root = word[len(affix):]
    frequency = max(zipf_frequency(word, lang)
                    for lang in ('en', 'fr', 'de', 'es'))
    root_frequency = zipf_frequency(root, 'en')
    for ending in ('ing', 'ed', 's', 'es', 'ation', 'ment', 'al', 'ly', 'ity'):
        if root.endswith(ending) and len(root) > len(ending) + 2:
            bare = root[:-len(ending)]
            root_frequency = max(root_frequency,
                                 zipf_frequency(bare, 'en'),
                                 zipf_frequency(bare + 'e', 'en'))
    return (affix, root_frequency, max(0., root_frequency - frequency),
            max(0., 5. - frequency), ACTION_STARTS.get(root, 0.))


def response(affix, joined, root_frequency, root_excess,
             rarity, action_completion, new_letters):
    if not joined:
        return 0.01
    # Large frequency gaps favor a compositional, rather than memorized, word.
    if root_excess > 2.25:
        if affix == 're':
            if action_completion <= 3.25:
                return 1.14
            return 1.91 if new_letters <= 2 else 3.35
        if affix in ('in', 'sub', 'con'):
            return 0.06
        if action_completion <= 0.25:
            return 2.54 if affix == 'over' else 0.55
        return 0.46 if affix == 'dis' else 1.35
    if action_completion <= 2.75:
        return 0.06
    if affix == 're':
        if root_excess <= 1.25:
            return 1.60 if root_frequency <= 2.25 else 0.63
        return 1.19 if new_letters <= 3 else 2.46
    if affix == 'over':
        return 1.49
    return 0.09 if rarity <= 1.75 else 0.46


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prior = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    joined = bool(prior and (LETTERS.match(token) or token.startswith('-')))
    if joined:
        match = LETTERS.match(token.lstrip('-'))
        part = match.group() if match else ''
        word = (prior + part).lower()
    else:
        match = LETTERS.search(token)
        part = match.group() if match else ''
        word = part.lower()

    # The final alphabetic run is the only state needed at the next token.
    tail = re.search(r'([A-Za-z]+)-?$', token)
    if tail:
        next_word = tail.group(1)
        if joined and tail.start() == len(token) - len(token.lstrip('-')):
            next_word = prior + next_word
    else:
        next_word = prior if token == '-' else ''
    features = word_features(word)
    value = 0.
    if features is not None:
        affix, root_frequency, root_excess, rarity, action_completion = features
        value = response(affix, joined, root_frequency, root_excess,
                         rarity, action_completion, len(part))
    return (doc, next_word), float(value)

"""A conversation-boundary signal, not a topic detector.

End-of-message tokens are strongly positive, less so after tool markup.
Closing a tool call or a reasoning section is a weaker positive signal.
These signals are smaller with little preceding document context. The
end-of-message estimate is also stronger after punctuation than letters.
Ordinary tokens are approximated by zero.
