        if position == 0:
            value = 0.512
        elif previous == '</tool_call>':
            value = 2.31 - 6.15 / (position + 2.47)
        elif previous == '</tool_response>':
            value = 2.22 - 5.84 / (position + 1.32)
        else:
            value = 2.86 - 4.31 / (position + 2.64)
            letters = [ch for ch in previous if ch.isalpha()]
            if letters:
                non_latin = any('LATIN' not in unicodedata.name(ch, '')
                                for ch in letters)
                value -= 0.29 if non_latin else 0.13
            elif any(unicodedata.east_asian_width(ch) in ('W', 'F')
                     for ch in previous):
