        value = 1.04 - 2.08 / (position + 2.64)
    elif token == '</tool_response>':
        value = -0.145 - 0.134 / (1 + position / 200)
    elif token == '</think>':
        value = 0.47 - 5.42 / (position + 13.2)
    elif token == '<think>':
        value = -0.048 - 4.01 / (position + 14.1)
    elif token == '<|im_start|>':
        value = 0.022 - 2.58 / (position + 18.7)
    elif token == '<|endoftext|>':
        value = 0.6 if position == 0 else -0.02

    return (doc, position + 1, token), float(value)

