"""Full stops after abbreviations, and digits in hyphenated codes (layers.1.mlp.down_proj:5105).

What it does, in plain terms:
- A full stop that closes an abbreviation or an initial fires. Strongest after the case-name
  abbreviations "v" and "vs" ("Roe v. Wade"), then after titles, saints and street names
  ("Mr.", "Ms.", "Dr.", "St.", "Ft.", "Lt."), then other short capitalised abbreviations
  ("No.", "Inc.", "Jr.") and single letters ("J.", "p.", "f."). A full stop after an ordinary
  word, or at a sentence end, stays silent.
- The space right after such a full stop ("No. 47", "Mr. Smith") fires weakly.
- A digit right after a hyphen or dash fires when it codes or ranges something: strongest after
  an all-capitals code ("F-1", "K-3", "WT-1"), moderately after a number ("9-1", "1-18").
- "w/" (short for "with") fires strongly on its slash; a digit after a slash fires weakly.
- A rare, very large spike: the colon right after a document-initial "Title" (the first token
  of a document is "Title", the second is ":"). It is about 36.7 there every time.
Everything else is 0. The ordinary cases are scaled by SCALE (0.5) because full-strength
versions disturb the model more than they help; the spike is left at full value.
"""

READS = ()

CASE_NAME_WORDS = {"v", "vs"}  # "Roe v. Wade", "Smith vs. Jones"
TITLE_WORDS = {"Mr", "Mrs", "Ms", "Dr", "St", "Lt", "Ft", "Mt", "Sr", "Ave"}
HYPHENS = {"-", "–"}
SCALE = 0.5  # multiplier on the ordinary cases (not the spike)


def _same_doc(prefix, i):
    """True if tokens i-1 and i belong to the same document."""
    return i >= 1 and prefix.document_ids[i] == prefix.document_ids[i - 1]


def _word(prefix, i):
    """Token i decoded alone, without surrounding spaces; "" before the row starts."""
    return prefix.token_strings[i].strip() if i >= 0 else ""


def _is_short_capitalised(word):
    """Capitalised abbreviation of up to three letters, such as "No" or "Inc"."""
    return word[:1].isupper() and word[1:].islower() and len(word) <= 3


def step(carry, prefix, upstream):
    carry, value = _step(carry, prefix, upstream)
    return carry, value if value > 30 else value * SCALE


def _step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or not _same_doc(prefix, t):
        return carry, 0.0
    cur = _word(prefix, t)
    prev = _word(prefix, t - 1)
    prev2 = _word(prefix, t - 2)

    if cur == ":" and prev == "Title" and not _same_doc(prefix, t - 1):
        return carry, 36.7  # the one very large spike

    if cur == ".":
        if prev in CASE_NAME_WORDS:
            return carry, 2.0
        if prev in TITLE_WORDS:
            return carry, 1.5
        if len(prev) == 1 and prev.isalpha():
            return carry, 0.6  # initials and single-letter citations
        if _is_short_capitalised(prev):
            return carry, 0.7
        if prev.islower() and len(prev) <= 3:
            return carry, 0.25  # "etc.", "al.", "ca."
        return carry, 0.0

    if prefix.token_strings[t].strip() == "" and prev == "." and _same_doc(prefix, t - 1):
        # The space after an abbreviation's full stop ("No. 47", "Mr. Smith").
        if len(prev2) == 1 or _is_short_capitalised(prev2):
            return carry, 0.35
        return carry, 0.0

    if cur.isdigit() and prev in HYPHENS:
        if prev2.isupper() and len(prev2) <= 3:
            return carry, 1.1  # codes such as "F-1", "K-3", "WT-1"
        if prev2.isdigit():
            return carry, 0.45  # ranges and scores such as "9-1", "1-18"
        return carry, 0.15

    if cur.isdigit() and prev == "/":
        return carry, 0.2
    if cur == "/" and prev == "w":
        return carry, 2.5  # "w/" for "with"
    return carry, 0.0

