"""A sparse spelling-family approximation, chiefly for climbing and crawling.

Track the unfinished Latin-letter word, resetting at document boundaries.
Climb/crawl spellings give negative responses, stronger when split into
pieces; Chinese climb/crawler spellings are negative too. Crooked is positive.
Smaller signed rules cover claw/scrape/scrub, comb, swab/swim, curl/curb/crank,
some cre- fragments, labial-ending blends, capitalized Crown in restricted
contexts, and PHP opening tags. Everything else defaults to zero.
"""
import re

READS = ()
BLEND = r'(?:cr|cl|scr|sw|schw|squ|sk|kr)'


def response(word, old, token, previous):
    split = bool(old)
    if '爬' in token or (token == '虫' and previous.endswith('爬')):
        return -7.0
    if token == 'php' and previous.endswith('<?'):
        return -1.5
    if re.search(r'climb(?:s|ed|er|ers|ing)?$', word):
        return -11.0 if split else -6.2
    if word.endswith('clim'):
        return -6.5 if split else -2.0
    if re.search(r's?craw(?:l(?:s|ed|er|ers|ing|en)?|)$', word):
        return -8.0 if split else -5.8
    if word.endswith('crooked'):
        return 7.0 if old.endswith('cro') else 2.0
    if re.search(r'claw(?:s|ed|ing)?$', word):
        return -3.0
    if re.fullmatch(r'scrap(?:e|es|ed|er|ers|ing|y)', word):
        return -2.8
    if word == 'scrap':
        return -1.0
    if re.fullmatch(r'scrub(?:s|bed|bing)?', word):
        return -1.4
    if re.fullmatch(r'(?:honey|back)?comb(?:s|ed|er|ers|ing)?', word):
        return -2.2 if split else -0.3
    if word.endswith('swab'):
        return -4.0 if split else -0.5
    if word == 'swam':
        return -3.6 if split else -0.3
    if word.startswith('swimm'):
        return -2.0 if split else -0.3
    if token.strip() == 'Crown' and previous.strip().lower() not in (
        'the', 'a', 'your', 'of'
    ):
        return 1.2
    if word in ('curl', 'curb'):
        return -0.7
    if word == 'crank':
        return -1.4
    # A blend plus a vowel and b/m, completed across a token boundary.
    blend = re.fullmatch(r'(?:c|sc|' + BLEND + r')[aeiou]?m?', old)
    if blend and re.fullmatch(BLEND + r'[aeiou]m?bb?', word):
        return -7.0 if word.endswith(('mb', 'bb')) else -2.8
    if blend and re.fullmatch(BLEND + r'[aiu]m', word):
        return -2.3
    if split and word in ('concre', 'recre', 'discre'):
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    same = carry is not None and carry[0] == document
    old, previous = carry[1:] if same else ('', '')
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+$', token)
    fragment = old if match and match.start() == 0 else ''
    word = fragment + match.group().lower() if match else ''
    value = response(word, fragment, token, previous)
    return (document, word[-32:], token), value

