    value = -0.003

    if token == '.com' and tail.endswith('githubusercontent'):
        value = -1.76
    elif token == '.com' and tail.endswith('github'):
        if previous.startswith('.'):
            value = -0.06  # The API subdomain fires later, at /repos.
        elif previous.endswith('"github'):
            value = -2.0
        elif previous[:1].isspace():
            value = -1.18
        elif previous == 'ithub':  # GitHub split after a tab-prefixed g.
            value = -1.32
        elif tail.endswith('://github'):
            value = -1.67
        elif tail.endswith('\ngithub'):
            value = -1.2
        else:
            value = -1.5
    elif token == '.in' and tail.endswith('gopkg'):
        value = -1.05
    elif token == '.org' and tail.endswith('bitbucket'):
        value = -0.8
    elif token == '/repos' and tail.endswith('api.github.com'):
        value = -0.86

