"""Program E: the first token of each document, by kind of token; middle-dot filler; 'this' in prose.

Why: at a document's first token the model has no earlier context, so this component's
activation there depends only on which token it is. Coarse kinds of token explain part of that.
"""
import re

READS = ()

FUNCTION_WORDS = {
    "the", "of", "and", "to", "a", "in", "is", "that", "it", "for", "with", "as", "was", "on",
    "be", "are", "by", "or", "from", "at", "an", "not", "i", "this", "these", "they", "we",
    "if", "but", "when", "how", "for", "he", "she", "you", "there", "what", "its",
}
CODE_STARTS = {"#", "//", "/*", "<?", "import", "#include", "#!/", "/"}
PUNCTUATION = set(",.:;!?-()\"'")
DEMONSTRATIVES = {" this", " These", " these", " This", "This", "These"}
CODE_CHARS = set("{}();=<>[]$\\_#*&|@/\t")
