def first_token_value(tok):
    """Activation on a document's first token, from the kind of token it is."""
    word = tok.strip().lower()
    if tok in CODE_STARTS:
        return 0.2  # code or comment openers: '#', '//', 'import'
    if tok.strip() == "":
        return 0.4  # whitespace on its own
    if tok == "0":
        return -0.8  # the digit zero is an exception among digits
    if re.fullmatch(r"\s?[1-9]+", tok):
        return 3.3
    if "\n" in tok:
        return 3.4
