        return 2.5  # common function words: 'The', ' of', ' and', ...
    if re.fullmatch(r" ?[A-Z][a-z]+", tok):
        return 0.9  # other capitalised words
    return 1.5  # other words


def looks_like_code(text):
    """True if the recent tokens are mostly code-like."""
    return sum(1 for s in text if s and (s[0] in CODE_CHARS or s[-1:] in CODE_CHARS)) > len(text) / 3


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, first_token_value(tok)
    if tok == "··":
        return carry, 3.4  # the middle-dot filler token
    if tok in DEMONSTRATIVES and not looks_like_code(prefix.token_strings[-16:-1]):
        return carry, 0.6  # 'this' / 'these' in running prose
    return carry, 0.0

programs.sol:
"""A line-opening punctuation signal, strongest on list continuations.

A single newline differs sharply from a paragraph break. Responses adapt
as a run of lines grows, and depend on indentation and whether the previous
line was another list item, ended a sentence, or introduced a list with ':'.
Single hash signs have a separate, often negative response. Document-title
field colons and numeric view counters are additional structural cues.
Fitted formulas approximate these effects; other text gets zero.
"""
import math
import re

READS = ()
LIST_START = re.compile(r'\s*(?:[•*\-]|\d+[.)])')


def fresh(document):
    return dict(document=document, position=0, line='', breaks=0,
                run_lines=0, totals={}, colon=False, list_item=False,
                sentence_end=False, document_open=False)


def marker(token, line):
    text = token.strip()
    leading = not line.strip(' \t>')
    number = bool(re.fullmatch(r'[ \t>]*\d+', line))
    if leading:
        if text in ('•', '-', '*', '>'):
            return {'•': 'bullet', '-': 'dash', '*': 'star',
                    '>': 'quote'}[text]
        if text and set(text) == {'#'}:
            if len(text) == 1:
                return 'hash'
            return 'heading' if len(text) <= 6 else 'hash_rule'
    if number:
        if text == '.':
            return 'numberstop'
        if text in (')', ':', '-'):
            return 'numberclose'
        if text == 'views':
            return 'views'
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    c = fresh(doc) if carry is None or carry['document'] != doc else carry
    token, line = prefix.token_strings[-1], c['line']
    kind = marker(token, line)
    context = ('single' if c['breaks'] == 1 else
               'blank' if c['breaks'] >= 2 else 'start')
    repeat = 1 / math.sqrt(1 + c['totals'].get(kind, 0))
    run = 1 / math.sqrt(1 + c['run_lines'])
    early = 1 / math.sqrt(1 + c['position'])
    spaces = len(line) - len(line.lstrip(' \t'))
    spaces += len(token) - len(token.lstrip(' \t'))
    indent = math.log1p(spaces)
    colon, item, end = c['colon'], c['list_item'], c['sentence_end']
    merged_newline = '\n' in token
    space_prefixed = token.startswith((' ', '\t'))
    value = 0.0
    if context == 'single':
        if kind == 'bullet':
            value = (1.20 - .501 * repeat - 2.122 * colon
                     + 5.763 * run - 1.86 * space_prefixed)
        elif kind == 'dash':
            value = (-.258 - .426 * indent + 2.893 * run
                     + .818 * item + .597 * end)
        elif kind == 'numberstop':
            value = (-.555 - .498 * indent - .704 * colon
                     + 3.590 * run + .619 * item)
        elif kind == 'star':
            value = (.512 + .421 * run + .263 * item
                     + .217 * end - .818 * space_prefixed)
        elif kind == 'hash':
            value = (-.266 - .657 * repeat + .315 * indent
                     + 1.153 * merged_newline - .703 * end)
        else:
            value = {'heading': -.746, 'hash_rule': -.130,
                     'numberclose': .086, 'quote': .10}.get(kind, 0.)
    elif context == 'blank':
        if kind == 'numberstop':
            value = -.017 + .289 * repeat + .211 * colon
        elif kind == 'hash':
            value = (.053 + .410 * repeat + .577 * early
                     - .187 * space_prefixed)
        else:
            value = {'bullet': .208, 'dash': .431, 'star': .164,
                     'heading': .787, 'hash_rule': -.164,
                     'numberclose': .016, 'quote': .077}.get(kind, 0.)
    else:
        value = {'bullet': -.140, 'dash': .279, 'star': .117,
                 'heading': -.226, 'hash': .043, 'numberstop': .15,
                 'numberclose': .046, 'quote': .695}.get(kind, 0.)
    if kind == 'views':
        value = 1.03
    if token == ':' and line == 'Title' and c['document_open']:
        value = 3.88
    # Update only from the newest token; never rescan the prefix.
    if kind != 'other':
        c['totals'][kind] = c['totals'].get(kind, 0) + 1
    parts = token.split('\n')
    for i, part in enumerate(parts):
        c['line'] = (c['line'] + part)[-2000:]
        if i == len(parts) - 1:
            break
        c['document_open'] = False
        completed = c['line'].rstrip()
        if completed:
            c['breaks'] = 1
            c['colon'] = completed.endswith((':', '：'))
            c['list_item'] = bool(LIST_START.match(completed))
            c['sentence_end'] = completed.endswith(('.', '!', '?', '。', '！', '？'))
        else:
            c['breaks'] += 1
        if c['breaks'] >= 2:
            c['run_lines'] = 0
        c['run_lines'] += 1
        c['line'] = ''
    if '<|endoftext|>' in token:
        c['line'], c['breaks'], c['run_lines'], c['totals'] = '', 0, 0, {}
        c['document_open'] = True
    c['position'] += 1
    return c, float(value)

"""Mostly an a-like token response, conditional on the surrounding language.

The Romance preposition a (including accented forms) responds much more than
English a. A few Chinese transcription characters and Korean a also respond.
Two secondary patterns are middle-dot dividers and video 'likes - added' text.
Unmodelled, generally small, responses are left at zero.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'es', 'it', 'pt', 'fr', 'ro', 'de')
AMPLITUDES = (-0.01, 1.18, 1.41, 0.37, 0.70, 0.45, 0.13)


@lru_cache(maxsize=20000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language_response(text, capital):
    text = re.sub(r'<\|.*?\|>|</?think>', ' ', text)
    words = re.findall(r'[^\W\d_]+', text.lower())[-16:]
    scores = [4.0] + [0.0] * (len(LANGUAGES) - 1)
    for age, word in enumerate(reversed(words)):
        for i, freq in enumerate(frequencies(word)):
            scores[i] += 0.5 * 0.85 ** age * freq
    high = max(scores)
    weights = [math.exp(s - high) for s in scores]
    amplitudes = list(AMPLITUDES)
    if capital:
        # Capital A at a sentence start is a word; elsewhere often a name
        # or a mathematical label. French sentence-initial A is stronger.
        boundary = not text.strip() or bool(
            re.search(r'[.!?¿:;]\s*$|\n\s*$', text)
        )
        amplitudes[4] = 1.55 if boundary else 0.6
        if not boundary:
            amplitudes[1] *= 0.35
            amplitudes[2] *= 0.35
    return sum(w * a for w, a in zip(weights, amplitudes)) / sum(weights)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token in (' a', ' A', 'a', 'A', ' ad', ' Ad'):
        inside_word = token in ('a', 'A') and previous and previous[-1].isalpha()
        if not previous:
            value = 0.73 if token == ' a' else 0.6
        elif not inside_word:
            value = language_response(previous, token.strip().startswith('A'))
    elif token in (' à', ' á', ' Á'):
        value = 1.25
        if token == ' á':
            value = 0.95 if language_response(previous, False) > 0.2 else 0.1
    elif token == "'à":
        value = 0.88
    elif token == ' À':
        boundary = not previous or re.search(r'[.!?]\s*$|\n\s*$', previous)
        value = 1.6 if boundary else -0.05
    elif token == '阿':
        value = 6.2
    elif token == '巴':
        value = 6.8 if previous.endswith(('鸡', '雞')) else 4.0
    elif token in ('乌', '烏'):
        value = 3.5
    elif token.strip() == '아':
        value = 2.35 if token.startswith(' ') else 0.8
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -1.75
    elif token == ' added':
        value = 10.3 if re.search(r'\d+ likes?\s*-\s*$', previous) else -0.18
    return (doc, (previous + token)[-260:]), value

"""Short grammatical collocations, rather than a general word detector.

Positive rules recognize infinitival complements, search/anticipation
expressions, and relational phrases such as 'with regard'. Selected copular
comparisons and clause introductions ('is like/when/because') are negative.
Chinese degree and spatial constructions get a smaller parallel treatment.
The two previous tokens and a short text tail supply context; document
boundaries reset them. Unrecognized constructions are left at zero. This
is a sparse approximation, not a model of the small lexical background.
