INFINITIVES = {
    'supposed': 4.4, 'suppose': 3.8, 'meant': 3.4,
    'intended': 1.8, 'opposed': 1.45, 'designed': 1.1,
    'guaranteed': 1.0, 'allowed': 0.95, 'trying': 0.8,
    'assumed': 0.8, 'hoping': 0.6, 'expected': 0.55,
    'permitted': 0.5, 'attempting': 0.5, 'required': 0.46,
    'referring': 0.4, 'looking': 0.35, 'going': 0.2,
}
