CHINESE_INSIDE_OUTSIDE = {'之中', '之外', '当中', '當中'}
CHINESE_LOCATION = {'以外', '以后', '以後', '之上', '之下',
                    '之内', '之內', '内的', '內的', '范围内', '範圍內'}
SCALAR = set(
    '大小多少高低长長短快慢早晚深浅淺远遠近'
    '重轻輕强強弱宽寬窄久'
)


def step(carry, prefix, upstream):
