    if word == 'to':
        value = INFINITIVES.get(prev, 0.0)
        contracted = before in {"'s", '’s', "'m", '’m', "'re", '’re'}
        passive = before in COPULAS or before == 'not'
        if prev == 'supposed':
            value = 6.0 if contracted or before == 'am' else 4.2
        elif prev == 'meant':
            value = 4.6 if contracted else (3.4 if passive else 1.7)
        elif prev == 'intended':
            value = 2.2 if passive else 0.7
        elif prev in {'designed', 'trying', 'hoping', 'required', 'allowed'}:
            value *= 1.3 if passive else 0.6
        if prev == 'forward':
            value = 1.0 if before in {'looking', 'look'} else 0.15
    elif word == 'for':
        if prev == 'looking':
            value = 2.5 if before in {'is', 'are', 'am'} else 1.2
            if before in {"'re", '’re', "'m", '’m', "'s", '’s'}:
                value = 2.9
            elif before in {'was', 'were', 'be', 'been'}:
                value = 1.9
        elif prev in {'waiting', 'asking', 'searching', 'wishing'}:
            value = 0.8
        elif prev in {'look', 'check', 'asked', 'searched'}:
