        elif prev in {'intended', 'meant'}:
            value = 0.9
        elif prev in {'designed', 'prepared', 'scheduled', 'except'}:
            value = 0.4
    elif word == 'forward':
        if prev == 'looking':
            value = 3.1
        elif prev in {'look', 'looks', 'looked'}:
            value = 1.6
        elif prev in {'moving', 'move'}:
