        elif word in {'hoping', 'guessing'}:
            value = 1.3
        elif word in {'intended', 'concerned', 'followed', 'afraid'}:
            value = 0.6
        elif word in {'interested', 'worried', 'meant'}:
            value = 0.35
        elif word in {'due', 'against'}:
