    elif word == 'supposed':
        value = 2.3 if prev == 'not' else 1.0
    elif word == 'opposed' and prev == 'as':
        value = 1.2
    elif word == 'allowed' and prev == 'not':
        value = 0.95
    elif word == 'sure' and prev in {'not', 'pretty', 'quite'}:
        value = 0.5
    elif word == 'when' and prev == 'even':
        value = -0.5
    elif word == 'at' and prev == 'aimed':
        value = 0.7
    elif word == 'associated' and prev in {
