"""Component layers.1.mlp.down_proj:5113: fixed phrases that take a "to" or "for" complement
(positive), and copular or causal connectives (negative).

What it does, in plain terms:
- Positive, strongest on "to": "supposed to" and "meant to" (what is supposed or meant to
  happen). Next: "to" after intended, opposed ("as opposed to"), designed, allowed, trying,
  expected, required, forward and similar intention or expectation words; and the "be" that
  follows "considered / intended / meant to".
- Positive on "for" after seeking, waiting or intention words: "looking for", "waiting for",
  "searching for", "asking for", "intended for", "designed for".
- Positive on the word that opens such a phrase: "supposed" (after is/was/are), "forward"
  after "looking", "regard" after "with", "opposed" after "as".
- Positive on some Chinese words of hope, expectation and comparison (希望, 期待, 比较, 较,
  过程中, 空间, 关注).
- Negative on a connective right after a copula, as in "That's when", "This is because",
  "It's like", "is where", and "is the way". These introduce an explanation or description.
- Negative on a few Chinese words of cause and undergoing (受到, 使得, 直接, 接受, 感到).
- Slightly negative on the first token of each document.
- Near zero everywhere else. Plain infinitives ("want to", "need to") and prepositional "to"
  ("due to", "similar to") do not fire.

Built from word lists, not from the model. It reads only the current token and the two or
three tokens before it, within the same document.
"""

READS = ()

SUPPOSED_TO = {"supposed", "meant"}
# "to" after these: intention, design, permission, expectation, obligation.
INTENT_TO = {"designed", "guaranteed", "allowed", "permitted", "trying", "attempting",
             "assumed", "presumed", "hoping", "expecting", "expected", "forward", "intend",
             "intends", "required", "aiming", "aimed", "considered"}
# "to" after these: the strongest of the intention words.
HIGH_INTENT_TO = {"intended", "opposed"}
# "to" after these: weaker expectation or appearance verbs.
WEAK_TO = {"likely", "unlikely", "appears", "appear", "appeared", "seems", "seem", "seemed",
           "going", "said", "referring", "regards", "expect", "expects", "aims", "aim",
           "predicted", "suggested", "believed", "known", "prefers", "advised", "starting",
           "planning"}
# "for" after these: seeking or waiting.
SEEK_FOR = {"looking", "waiting", "searching", "asking"}
INTENT_FOR = {"intended", "meant", "designed", "prepared"}
LOOK = {"look", "looked"}
COPULA = {"is", "was", "s", "’s", "are", "were", "be", "am"}
CLEFT = {"when", "because", "where", "like"}
CN_POS = {"希望": 0.5, "期待": 0.4, "比较": 1.2, "比較": 1.2, "较": 0.3, "較": 0.3,
          "过程中": 0.7, "空间": 0.5, "关注": 0.4}
CN_NEG = {"受到": -0.7, "使得": -0.4, "直接": -0.3, "接受": -0.3, "感到": -0.3}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    if len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, -0.13  # first token of a document
    prev = prefix.token_strings[-2].strip()
    prev_l = prev.lower()
    prev2 = ""
    if len(prefix) > 2 and prefix.document_ids[-3] == prefix.document_ids[-1]:
        prev2 = prefix.token_strings[-3].strip()
    if cur in CN_POS:
        return carry, CN_POS[cur]
    if cur in CN_NEG:
        return carry, CN_NEG[cur]
    if cur == "to":
        if prev_l in SUPPOSED_TO or prev_l.startswith("suppos"):
            value = 4.0
        elif prev_l in HIGH_INTENT_TO:
            value = 1.7
        elif prev_l in INTENT_TO:
            value = 0.8
        elif prev_l in WEAK_TO:
            value = 0.25
        else:
            value = 0.0
    elif cur == "for":
        if prev_l == "looking":
            value = 2.0
        elif prev_l in SEEK_FOR or prev_l in INTENT_FOR:
            value = 1.0
        else:
            value = 0.0
    elif cur == "be" and prev == "to" and (prev2 in INTENT_TO or prev2 in SUPPOSED_TO
                                           or prev2 in HIGH_INTENT_TO):
        value = 0.8
    elif cur.lower() == "supposed" or cur.lower().startswith("suppos"):
        value = 2.5 if prev in COPULA else 0.5
    elif cur == "forward":
        value = 3.0 if prev_l == "looking" else (1.5 if prev_l in LOOK else 0.4)
    elif cur == "regard":
        value = 2.0 if prev_l == "with" else 0.2
    elif cur == "opposed":
        value = 1.3 if prev_l == "as" else 0.2
    elif cur in CLEFT and prev in COPULA:
        value = -1.5
    elif cur == "way" and prev == "the" and prev2 in COPULA:
        value = -1.0
    else:
        value = 0.0
    return carry, float(value)

