"""Approximate the negative response to split whitespace padding.

Most important harvested examples were single-space tokens following another
padding token. Their predicted response depends on padding width, indentation,
and how early the position is in the document. Escaped double backslashes are
negative, while TeX row-break syntax is positive. Line-initial 1 is weakly
negative. Coarse document-start corrections cover whitespace, code keywords,
digits and ASCII letters; initial 12 has a large negative exception.
Everything else is approximated by zero.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, '', '', '')
    _, position, indentation, previous, recent, initial = carry
    s = prefix.token_strings[-1]
    value = 0.0

    if s == ' ':
        if previous and not previous.strip(' '):
            n = len(previous)
            if n == 1:
                value = -0.31 if indentation is not None else 0.0
            else:
                value = -0.43
                if n <= 3:
                    value = -0.52 if n == 2 else -0.55
                elif n == 4:
                    value = -0.62
                if indentation is None:
                    value += 0.12 if n < 5 else 0.0
                value -= 0.18 * math.exp(-position / 45)
        elif previous.endswith('\n'):
            value = -0.08 - 0.08 * math.exp(-position / 45)
        elif previous.endswith('n') and '\\' in recent[-4:]:
            value = -0.22
    elif '\\\\' in s or (s == 'cr' and previous.endswith('\\')):
        latex = any('\\' + command in recent for command in
                    ('right', 'left', 'begin', 'hfill', 'big', 'quad', 'frac',
                     'sqrt', 'math', 'text', 'pmatrix', 'nonumber', 'infty'))
        if latex or s.endswith('\n'):
            value = 2.8 if s == 'cr' else 1.5
        elif s.count('\\') == 2:
            value = -0.8
    elif s == '1' and indentation is not None and position:
        value = -0.28 if indentation not in (3, 4) else 0.0

    # Coarse corrections for the unconditioned start of a document.
    if position == 0:
        if s in {'import', 'export', 'def', 'int', 'string'}:
            value = 2.85
        elif s in {'using', 'package'}:
            value = -1.2
        elif s in {'\t', '\\t'}:
            value = 2.7
        elif s == '  ':
            value = -1.07
        elif s == '   ':
            value = 0.45
        elif s == '    ':
            value = -1.25
        elif s == ' ':
            value = -0.09
        elif s.isdigit() and len(s) == 1:
            value = 0.4 if s != '0' else -0.11
        elif len(s) == 1 and s.isascii() and s.isalpha():
            if s.islower():
                value = -0.15 if s in 'aeiou' else -0.65
            else:
                value = -0.2
    elif position == 1 and initial == '1' and s == '2':
        value = -5.08
    elif position == 2 and initial == '12' and s == '2':
        value = -1.57

    # Track whether the current line still contains only indentation.
    if '\n' in s:
        end = s.rsplit('\n', 1)[-1]
        indentation = len(end) if not end.strip(' ') else None
    elif indentation is not None:
        indentation = indentation + len(s) if not s.strip(' ') else None
    if position < 2:
        initial += s
    return (doc, position + 1, indentation, s, (recent + s)[-180:], initial), value

"""A coarse document-start token-shape response and a middle-dot leader.

Identifier suffixes (especially an underscore followed by letters) are
positive. Unspaced words and indentation are generally negative. An
unbroken run of middle dots from the start stays negative. Elsewhere,
predict zero instead of the smaller, varied lexical responses. The
coefficients are training averages, not individual-token lookups.
"""

READS = ()


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    s = prefix.token_strings[-1]
    # A document containing only a repeated middle-dot separator so far.
    dot_run = bool(s) and not s.strip('·') and (first or carry)
    if dot_run:
        return True, -0.74
    if not first:
        return False, 0.0
    word = s.lstrip()
    spaced = word != s
    value = -0.15
    if s.startswith('<|'):
        value = -0.28
    elif s.isspace():
        if '\t' in s:
            value = -0.9
        elif '\n' in s or '\r' in s:
            value = -0.44
        else:
            value = -0.04 if len(s) == 1 else -0.74
    elif len(s) > 1 and s[0] in '_-/' and s[1].isalpha():
        value = {'_': 0.77, '-': 0.21, '/': 0.3}[s[0]]
        if s[0] == '_' and len(s) == 2 and s[1].isascii():
            value = 1.4
    elif word.isdigit():
        value = -0.06
    elif word.isalpha():
        if spaced:
            value = 0.0 if len(word) == 1 or word.isupper() else -0.11
        elif len(word) == 1 and word.isascii() and word.islower():
            value = -0.55
        else:
            value = (-0.06 if len(word) > 1 and word.isascii()
                     and word.isupper() else -0.27)
    elif spaced and word and word[0] in '(\"\'':
        value = 0.54
    return False, value

"""A third-digit pulse in an uninterrupted run of ASCII decimal digits.

Small current digits and a middle digit of 1 strengthen the pulse.
Common year prefixes and comma-separated continuations weaken it.
Other numeric positions have small digit-dependent baselines; text is zero.
At document start a separate, short numeric start-up pulse is used.
State resets at each document boundary.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        run, before, recent = '', '', ''
    else:
        _, run, before, recent = carry
    token = prefix.token_strings[-1]
    if len(token) != 1 or token not in '0123456789':
        return (doc, '', '', (recent + token)[-2:]), 0.0
    if not run:
        before = recent
    run += token
    d, n = int(token), len(run)
    if n == 3:
        value = 0.55 - 0.01 * d
        if d <= 1:
            value += 0.20
        elif d == 2:
            value += 0.11
        if run[1] == '1':
            value += 0.37
        if run.startswith('18'):
            value -= 0.28
        elif run.startswith('19'):
            value -= 0.52
        elif 200 <= int(run) <= 202:
            value -= 0.44
            if run == '201':
                value -= 0.37
        if len(before) == 2 and before[-1] == ',':
            if before[-2] in '0123456789':
                value -= 0.48
        elif before.endswith('.'):
            value += 0.05
        elif before.endswith('\n'):
            value += 0.10
    elif n == 2:
        value = 0.15 if d == 1 else 0.03 if d == 0 else -0.08
    elif n == 4:
        value = 0.15 if d <= 1 else -0.06
    elif n > 4:
        value = 0.0 if d <= 2 else -0.11
    else:
        value = 0.02
    if not before:  # This digit run began at the document boundary.
        if n == 1:
            if d in (0, 9):
                value = -0.24 if d == 0 else -0.49
            else:
                value = 2.0 - 0.4 * d if d <= 4 else 0.4
        elif n <= 3:
            value = 0.85 if n == 2 else 0.80
        elif n == 4:
            value = 0.45
    return (doc, run, before, (recent + token)[-2:]), value

programs.haiku:
"""Third digit of a number.

Layer-1 MLP feature (down_proj component 5117). It is mostly silent, but it lights up on
the third digit of a run of digits: the "3" in 1234, the "5" in 50 5... (a digit that
follows exactly two digits in the same number). Its strength depends on the first two
digits of that number:
  - year-like numbers (starting 18, 19 or 20, e.g. 1984, 2010) are suppressed;
  - numbers whose second digit is 1 (e.g. 211, 310) are strongest;
  - everything else is moderate.
Digits in the first or second place, and non-digit tokens, predict 0.
A digit run restarts at each new document and after any non-digit token.
"""

from param_decomp.explain.atoms import FULLWIDTH_DIGITS

READS = ()

DIGITS = frozenset("0123456789") | FULLWIDTH_DIGITS
YEAR_STARTS = ("18", "19", "20")


def step(carry, prefix, upstream):
    run, head = (0, "") if carry is None else carry
    token = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        run, head = 0, ""
    if token in DIGITS:
        run += 1
        if run <= 2:
            head += token
    else:
        run, head = 0, ""
    value = 0.0
    if run == 3:
        if head in YEAR_STARTS:
            value = 0.1
        elif head[1] == "1":
            value = 0.9
        else:
            value = 0.55
    return (run, head), value

programs.sol:
"""A document-start and formatting-boundary approximation.

Initial numbers, quotes and a few punctuation/leader classes have large
responses. Preserve that response through an unbroken run of the opening
token. Elsewhere, ordinary words get zero; rules cover escaped prose line
breaks, paragraph/table boundaries, TeX breaks, and dense backtick markup
mixed with nonbreaking spaces. Vocabulary-specific fluctuations are omitted.
"""
import re

READS = ()

TEX_COMMAND = re.compile(
    r'\\(?:frac|text|begin|end|left|right|hfill|cdot|Gamma|boldsymbol)\b'
)


def initial(s):
    text = s.strip()
    if s.isascii() and s.isdigit():
        return 2.35
    if s == '\r':
        return -2.8
    if s == '\n':
        return 3.58
    if s == '\t':
        return 2.75
    if s == '\n\n':
        return 2.4
    if s.isspace():
        return 0.0
    if text == '**':
        return 7.8
    if text and set(text) == {'·'}:
        return 5.4
    if text in {'“', '”'}:
        return 3.75
    if text and set(text) <= {'"', "'"}:
        if len(text) >= 3:
            return 5.1
        if s.startswith(' '):
            return 4.3
        return 3.7 if text == '"' else 1.7
    if text == '.' and s.startswith(' '):
        return 6.7
    punctuation = text and not any(ch.isalnum() for ch in text)
    if text == '`':
        return 1.0
    if punctuation:
        if '\n' in s:
            return 1.8
        if text.startswith('(') and ')' not in text:
            return 1.8 + 1.5 * s.startswith(' ') + 2.2 * ("'" in text)
        if text.startswith(('\\', '`')):
            return 3.1
        if '*' in text or len(text) > 1 and set(text) <= {'#', '^'}:
            return 2.2
        if text.startswith(('{', '[')):
            return 1.5
        return 0.2
    return 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        state = (doc, s, s, '\xa0' in s, 0.0,
                 any(ch in s for ch in '{}[]=`'), s)
        return state, initial(s)
    _, previous, tail, nonbreaking, density, code, leading = carry
    leading = leading if s == leading else None
    text = s.strip()
    value = 0.0
    if '\n\n' in s:
        if text == '`':
            value = -0.3
        elif (previous in ('<think>', '</think>')
              or text == ':' and previous in ('Q', 'A')):
            value = -0.55
        elif s == '\n\n':
            value = -0.5 if re.search(r'\S {6,}\S', tail) else -0.08
        elif s.count('\n') >= 3:
            value = -0.18
        elif text.endswith((';', '}')):
            value = -0.1
    elif '`' in s and s.count('`') <= 2:
        if nonbreaking and density > 1:
            if text == '`':
                value = -1.05 if '`' in previous else -2.0
            elif text == '``':
                value = -1.2 if s.startswith(' ') else -0.35
            else:
                value = -0.5
    elif s == '\\n':
        value = 0.0 if code else -0.5
    elif s == 'n' and previous.endswith('\\'):
        value = -0.5 if not code and '        ' in tail else 0.0
    elif s.startswith('|') and text == '|' and '\n' in s:
        value = -0.9
    elif text == '\\\\':
        math = TEX_COMMAND.search(tail)
        value = -1.7 if math else (1.1 if code or '"' in previous else 0.0)
    elif '\xa0' in s and s.isspace() and density > 2:
        count = s.count('\xa0')
        value = -0.65 if count == 1 else 0.25
    # A homogeneous prefix retains the initial-token response.
    if leading is not None:
        value = initial(s)
    density = 0.9 * density + ('`' in s)
    code = code or any(ch in s for ch in '{}[]=`') or '\\t' in s
    state = (doc, s, (tail + s)[-100:],
             nonbreaking or '\xa0' in s, density, code, leading)
    return state, value

"""Notice Unicode characters that are still missing their final UTF-8 byte.

A separately tokenized middle byte produces the strongest response. Bare
character prefixes respond less; a leading space usually weakens them,
except for Korean syllables. Completed characters usually contribute nearly
zero. At document starts, word-like tokens get a separate positive baseline.
This tracks byte fragments, not literal replacement characters (U+FFFD).
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    pending = b'' if first else carry[1]
    token = prefix.token_bytes[-1]
    # Find the last UTF-8 lead byte; retain it only if still incomplete.
    raw = pending + token
    start = len(raw) - 1
    while start >= 0 and 0x80 <= raw[start] < 0xC0:
        start -= 1
    tail = raw[start:] if start >= 0 else b''
    size = (2 if tail and tail[0] < 0xE0 else
            3 if tail and tail[0] < 0xF0 else 4)
    if not tail or tail[0] < 0xC0 or len(tail) >= size:
        tail = b''
    value = -0.002
    if first:
        text = token.decode('utf-8', 'replace').strip()
        if text.isalpha():
            value = 0.20 if token.startswith(b' ') else 0.40
            if text.isupper():
                value = 0.03 if token.startswith(b' ') else 0.12
        elif text and not text.isdecimal() and not text.startswith('<|'):
            value = 0.16
    if tail:
        missing = size - len(tail)
        if missing == 1:
            if start < len(pending):
                # This token adds a middle byte, not the final byte.
                value = 0.95
                ch = (tail + b'\xa0').decode('utf-8', 'ignore')
                name = unicodedata.name(ch, '') if len(ch) == 1 else ''
                if size == 3 and 'GREEK' in name:
                    value = 1.50
                elif size == 3 and ('RUNIC' in name or 'OGHAM' in name):
                    value = 1.40
            elif token == tail:
                if size == 3:
                    # E0 covers several South/Southeast Asian scripts.
                    value = 0.22 if tail[0] == 0xE0 else 0.43
                    # E2 mostly covers punctuation and symbols.
                    if tail[0] == 0xE2:
                        value = 0.18
                else:
                    value = 0.55 if size == 4 else 0.25
                    if tail[0] == 0xC2:
                        value = 0.01
            elif token == b' ' + tail:
                # A filled-in byte identifies the character's broad block.
                ch = (tail + b'\x80').decode('utf-8', 'ignore')
                name = unicodedata.name(ch, '') if len(ch) == 1 else ''
                value = 0.52 if 'HANGUL' in name else 0.06
        elif token.startswith(b' ') and len(tail) == 1:
            # These lead bytes cover most Korean syllables.
            if 0xEB <= tail[0] <= 0xED:
                value = 0.40
    return (doc, tail), value
